"""
Test that the compiled photutils modules are free-threading compatible.
"""

import os
import subprocess  # nosec B404
import sys
import sysconfig
from importlib.machinery import EXTENSION_SUFFIXES
from pathlib import Path

import pytest

import photutils

GIL_DISABLED = bool(sysconfig.get_config_var('Py_GIL_DISABLED'))

# Generated by extension-helpers, whose module template does not declare
# free-threading support. Nothing in photutils imports it.
EXCLUDED_MODULES = {'photutils.compiler_version'}

# Run in a fresh interpreter. Each photutils subpackage is replaced
# by an empty stub so that its ``__init__`` module, which imports
# astropy, is not executed. Several astropy, pyerfa, and regions
# extension modules re-enable the GIL when imported, which would
# otherwise mask the result for the photutils modules. The name of the
# first module whose import leaves the GIL enabled is printed.
IMPORT_CODE = """
import importlib
import importlib.util
import pkgutil
import sys
import types

import photutils

for info in pkgutil.iter_modules(photutils.__path__, 'photutils.'):
    if info.ispkg:
        stub = types.ModuleType(info.name)
        spec = importlib.util.find_spec(info.name)
        stub.__path__ = spec.submodule_search_locations
        sys.modules[info.name] = stub

for modname in sys.argv[1:]:
    importlib.import_module(modname)
    if sys._is_gil_enabled():
        print(modname)
        break
"""


def find_compiled_modules():
    """
    Find the compiled extension modules in the photutils package.

    Returns
    -------
    modnames : list of str
        The sorted, fully qualified module names, excluding
        ``EXCLUDED_MODULES``.
    """
    root = Path(photutils.__path__[0])
    modnames = set()
    for path in root.rglob('*'):
        for suffix in EXTENSION_SUFFIXES:
            stem = path.name.removesuffix(suffix)
            # A stem containing a dot is an extension module built for a
            # different interpreter (e.g., "core.cpython-314-darwin").
            if stem != path.name and '.' not in stem:
                parts = path.relative_to(root.parent).with_name(stem).parts
                modnames.add('.'.join(parts))
    return sorted(modnames - EXCLUDED_MODULES)


@pytest.mark.skipif(not GIL_DISABLED,
                    reason='requires a free-threaded (GIL-disabled) build')
def test_compiled_modules_do_not_enable_gil():
    """
    Test that importing the compiled photutils modules does not
    re-enable the GIL on a free-threaded build.

    Each Cython module must be compiled with the
    ``freethreading_compatible=True`` directive, which declares it as
    free-threading compatible (``Py_MOD_GIL_NOT_USED``). Importing a
    module without that declaration re-enables the GIL.

    The modules are imported in a fresh interpreter so that extension
    modules from other packages (e.g., astropy) cannot affect the
    result. Any ``PYTHON_GIL`` environment variable is removed so that
    it cannot keep the GIL disabled.
    """
    modnames = find_compiled_modules()
    assert modnames

    env = {key: val for key, val in os.environ.items()
           if key != 'PYTHON_GIL'}
    # Use the import path of this process so that the child imports the
    # same photutils that was scanned above (e.g., a source tree that
    # pytest added to sys.path)
    env['PYTHONPATH'] = os.pathsep.join(sys.path)
    result = subprocess.run(  # noqa: S603  # nosec B603
        [sys.executable, '-c', IMPORT_CODE, *modnames], check=False,
        capture_output=True, text=True, env=env)
    assert result.returncode == 0, result.stderr
    assert result.stdout.strip() == ''
